#!/bin/bash
# Writes build/generated/BuildInfo.swift so the CLI and app know their version.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p build/generated
VERSION="$(tr -d '[:space:]' < VERSION)"
COMMIT="$(git rev-parse --short HEAD 2>/dev/null || echo unknown)"
cat > build/generated/BuildInfo.swift <<EOF
// Generated by scripts/gen-buildinfo.sh — do not edit.
extension AppIdentity {
    public static let version = "$VERSION"
    public static let commit = "$COMMIT"
}
EOF
